import {createLegacyControlAudit} from '../../../collect/legacy-control-audit.mjs';
import {createD1AtomicDriver} from '../../../storage/d1/atomic-driver';
import {createWebCrypto} from '../../../security/web-crypto.mjs';
export default {async fetch(request:Request,env:Env){if(new URL(request.url).pathname!=='/__fixture'||request.method!=='POST')return new Response('Not found',{status:404});const body=await request.json() as any,base=createWebCrypto();let fault=false;const crypto={...base,async sha256(bytes:Uint8Array){if(body.fault==='source-change'&&!fault){fault=true;await env.DB.prepare("UPDATE app_revisions SET revision=revision+1 WHERE name='source'").run();}return base.sha256(bytes);}};try{return Response.json(await createLegacyControlAudit({driver:createD1AtomicDriver(env.DB),crypto})[body.capture?'capture':'read'](body.input));}catch(error){return Response.json({error:String(error)},{status:409});}}};
